// Go: giới hạn 10 lời gọi đồng thời tới dịch vụ gợi ý
var recSem = make(chan struct{}, 10)

func callRecs(ctx context.Context) error {
    select {
    case recSem <- struct{}{}:
        defer func() { <-recSem }()
        return fetchRecs(ctx)
    default:
        return ErrBulkheadFull // fail nhanh, không chờ
    }
}
